<?php
require __DIR__.'/config.php'; require_role(['admin']);
$users=read_json('users');
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';
if($action==='create'){ $pass=$_POST['password']??''; if(strlen($pass)<12){flash('Password must be at least 12 characters.');}else{$users[]=['id'=>next_id($users),'username'=>trim($_POST['username']),'name'=>trim($_POST['name']),'email'=>trim($_POST['email']),'role'=>$_POST['role'],'password'=>password_hash($pass,PASSWORD_DEFAULT),'active'=>true,'created_at'=>date('c')];write_json('users',$users);log_action('create','user',end($users)['id']);flash('Account created.');}}
if($action==='toggle'){$id=(int)$_POST['id'];foreach($users as &$x)if((int)$x['id']===$id)$x['active']=!($x['active']??true);unset($x);write_json('users',$users);log_action('toggle','user',$id);flash('Account status updated.');}
redirect('accounts.php');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Accounts — Ridgefield</title><link rel="stylesheet" href="cms.css"><style>.wrap{max-width:1100px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:1fr 2fr;gap:18px}.card{border:1px solid #dde3dd;border-radius:14px;padding:20px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:9px;border-bottom:1px solid #ddd;text-align:left}input,select{width:100%;box-sizing:border-box;margin:5px 0 12px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style><link rel="stylesheet" href="assets/dynamic-site.css">
</head><body class="rf-dynamic"><div class="wrap"><p><a href="index.php">← Dashboard</a></p><h1>Account Management</h1><div class="grid"><div class="card"><h2>Create account</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="create"><label>Name<input name="name" required></label><label>Username<input name="username" required></label><label>Email<input type="email" name="email"></label><label>Role<select name="role"><option>teacher</option><option>parent</option><option>student</option><option>admin</option></select></label><label>Temporary password<input type="password" name="password" minlength="12" required></label><button>Create</button></form></div><div class="card"><h2>Accounts</h2><table class="table"><tr><th>User</th><th>Role</th><th>Status</th><th>Action</th></tr><?php foreach($users as $u):?><tr><td><?=h($u['name']??$u['username'])?></td><td><?=h($u['role']??'')?></td><td><?=($u['active']??true)?'Active':'Disabled'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$u['id']?>"><button><?=($u['active']??true)?'Disable':'Enable'?></button></form></td></tr><?php endforeach;?></table></div></div></div><script src="assets/dynamic-site.js"></script>
</body></html>